interface StoreSchema {
  users: Array<{ id: string; mobile: string; registeredAt: string; token: string }>;
  accounts: Array<{
    id: string;
    username: string;
    passwordHash: string;
    mobile: string;
    technicianName: string;
    role: 'admin' | 'technician' | 'user';
    biometricEnabled: boolean;
    lastLogin: string;
  }>;
  otps: Record<string, { code: string; expiresAt: number }>;
  devices: Array<{ deviceId: string; fingerprint: string; checksum: string; mobile: string; registeredAt: string }>;
  licenses: Array<{
    code: string;
    deviceId: string;
    mobile: string;
    status: 'active' | 'pending' | 'expired' | 'revoked';
    type: string;
    activatedAt: string;
    expiresAt: string;
  }>;
  logs: Array<{
    id: string;
    type: 'alarm' | 'connected' | 'test';
    title: string;
    timestamp: string;
    timeAgo: string;
    subtext: string;
    details: string;
    deviceId: string;
    ssid: string;
    statusBadge: string;
  }>;
  settings: {
    targetSSID: string;
    backgroundMonitoring: boolean;
    alertSoundType: 'he' | 'she' | 'classic' | 'continuous';
    soundVolume: number;
    fullScreenAlert: boolean;
    bootStart: boolean;
    drawOverApps: boolean;
  };
  pushSubscriptions: any[];
}

