// ----------------------------------------------------
// Activation Manager Algorithm (Kotlin ActivationManager.kt)
// ----------------------------------------------------
const MASTER_KEYS = new Set([
  "188703",
  "09159650802",
  "9159650802",
  "09038979972",
  "9038979972",
  "965965",
  "123456",
  "654321"
]);

function generateActivationCode(deviceCodeStr: string): string {
  const cleanCode = (deviceCodeStr || '').replace(/[^0-9]/g, '').trim();
  if (!cleanCode) return "000000";
  const num = parseInt(cleanCode, 10);
  if (isNaN(num) || num <= 0) return "000000";

  const raw = num * 191;
  const finalCode = (raw >= 100000 && raw <= 999999)
    ? raw
    : (raw % 900000) + 100000;

  return finalCode.toString().padStart(6, '0');
}

function validateActivationCode(deviceCodeStr: string, inputCode: string): boolean {
  const cleanInput = (inputCode || '').replace(/[^0-9]/g, '').trim();
  if (!cleanInput) return false;
  if (MASTER_KEYS.has(cleanInput)) return true;
  const expected = generateActivationCode(deviceCodeStr);
  if (cleanInput === expected) return true;
  return false;
}

