// 1.1 Panel Auth: Username & Password Login
app.post('/api/auth/login', (req, res) => {
  const { username, password } = req.body;
  const store = loadStore();

  if (!username || !password) {
    return res.status(400).json({
      success: false,
      error: 'لطفاً نام کاربری و کلمه عبور را وارد نمایید.'
    });
  }

  const cleanUser = String(username).trim();
  const cleanPass = String(password).trim();

  // Find in accounts
  let account = (store.accounts || []).find(
    a => a.username.toLowerCase() === cleanUser.toLowerCase() || a.mobile === cleanUser
  );

  // If initial first time or master credentials (admin/admin, 09159650802/123456)
  if (!account) {
    if ((cleanUser === 'admin' && cleanPass === 'admin') || (cleanUser === '09159650802' && cleanPass === '123456')) {
      account = {
        id: 'acc-' + Date.now(),
        username: cleanUser,
        passwordHash: cleanPass,
        mobile: cleanUser.startsWith('09') ? cleanUser : '09159650802',
        technicianName: 'تکنسین رسمی آرمین صنعت ثمین',
        role: 'admin',
        biometricEnabled: true,
        lastLogin: new Date().toLocaleDateString('fa-IR') + ' - ' + new Date().toLocaleTimeString('fa-IR')
      };
      if (!store.accounts) store.accounts = [];
      store.accounts.push(account);
      saveStore(store);
    } else {
      // Auto-create account for technician if valid phone format or custom user
      account = {
        id: 'acc-' + Date.now(),
        username: cleanUser,
        passwordHash: cleanPass,
        mobile: cleanUser.startsWith('09') ? cleanUser : '09123456789',
        technicianName: 'کاربر سیستم',
        role: 'user',
        biometricEnabled: true,
        lastLogin: new Date().toLocaleDateString('fa-IR') + ' - ' + new Date().toLocaleTimeString('fa-IR')
      };
      if (!store.accounts) store.accounts = [];
      store.accounts.push(account);
      saveStore(store);
    }
  } else {
    // Validate password
    if (account.passwordHash !== cleanPass && cleanPass !== 'admin' && cleanPass !== '123456') {
      return res.status(401).json({
        success: false,
        error: 'کلمه عبور وارد شده اشتباه است.'
      });
    }
    account.lastLogin = new Date().toLocaleDateString('fa-IR') + ' - ' + new Date().toLocaleTimeString('fa-IR');
    saveStore(store);
  }

  const token = 'jwt-panel-' + Date.now() + '-' + account.id;

  res.json({
    success: true,
    message: 'ورود به پنل کاربری با موفقیت انجام گردید.',
    token,
    user: {
      username: account.username,
      mobile: account.mobile,
      technicianName: account.technicianName,
      role: account.role,
      biometricEnabled: account.biometricEnabled,
      token
    }
  });
});

