// 2. Auth: Register Mobile & Generate Real OTP
app.post('/api/auth/register-mobile', (req, res) => {
  const { mobile } = req.body;
  if (!mobile || !/^09\d{9}$/.test(mobile.replace(/\s+/g, ''))) {
    return res.status(400).json({
      success: false,
      error: 'شماره تلفن همراه وارد شده نامعتبر است. فرمت صحیح: ۰۹۱۲۳۴۵۶۷۸۹'
    });
  }

  const cleanMobile = mobile.replace(/\s+/g, '');
  // Generate authentic 6-digit OTP
  const otp = Math.floor(100000 + Math.random() * 900000).toString();
  const expiresAt = Date.now() + 2 * 60 * 1000; // 2 minutes

  const store = loadStore();
  store.otps[cleanMobile] = { code: otp, expiresAt };
  saveStore(store);

  console.log(`[SMS-SERVICE] OTP for ${cleanMobile} is: ${otp}`);

  // In production commercial app, returns confirmation. We also return demoOtp so user can seamlessly test!
  res.json({
    success: true,
    message: `کد یک‌بار مصرف ۶ رقمی ارسال گردید: ${otp}`,
    otp, // helpful for preview verification
    expiresInSeconds: 120
  });
});

// 3. Auth: Verify OTP
app.post('/api/auth/verify-otp', (req, res) => {
  const { mobile, otp } = req.body;
  const cleanMobile = (mobile || '').replace(/\s+/g, '');
  const store = loadStore();

  const entry = store.otps[cleanMobile];
  // Allow test codes 849120, 123456 or generated otp
  const isValid = (entry && entry.code === otp && Date.now() < entry.expiresAt) ||
                  otp === '849120' ||
                  otp === '123456';

  if (!isValid) {
    return res.status(400).json({
      success: false,
      error: 'کد تایید وارد شده نامعتبر است یا منقضی شده است.'
    });
  }

  // Create or retrieve user
  let user = store.users.find(u => u.mobile === cleanMobile);
  if (!user) {
    user = {
      id: 'usr-' + Date.now(),
      mobile: cleanMobile,
      registeredAt: new Date().toLocaleDateString('fa-IR'),
      token: 'jwt-pmotor-' + Date.now()
    };
    store.users.push(user);
    saveStore(store);
  }

  res.json({
    success: true,
    message: 'احراز هویت با موفقیت انجام شد.',
    token: user.token,
    user
  });
});

// 4. Device Registration & Binding
app.post('/api/device/register', (req, res) => {
  const { deviceId, fingerprint, checksum, mobile } = req.body;
  if (!deviceId) {
    return res.status(400).json({ success: false, error: 'شناسه دیوایس الزامی است.' });
  }

  const store = loadStore();
  const existingIndex = store.devices.findIndex(d => d.deviceId === deviceId);

  const deviceRecord = {
    deviceId,
    fingerprint: fingerprint || `${deviceId} - 8920`,
    checksum: checksum || 'EF41-VALID',
    mobile: mobile || '09123456789',
    registeredAt: new Date().toLocaleDateString('fa-IR') + ' - ' + new Date().toLocaleTimeString('fa-IR')
  };

  if (existingIndex >= 0) {
    store.devices[existingIndex] = deviceRecord;
  } else {
    store.devices.push(deviceRecord);
  }
  saveStore(store);

  res.json({
    success: true,
    message: 'شناسه سخت‌افزاری دستگاه با موفقیت ثبت و مقید شد.',
    device: deviceRecord
  });
});

// 5. License Activation
app.post('/api/license/activate', (req, res) => {
  const { code, deviceId, mobile } = req.body;
  if (!code || code.length !== 6) {
    return res.status(400).json({
      success: false,
      error: 'کد فعال‌سازی باید ۶ رقم باشد.'
    });
  }

  const cleanCode = (code || '').replace(/[^0-9]/g, '').trim();
  const cleanDeviceId = (deviceId || '').replace(/[^0-9]/g, '').trim();
  const isAlgorithmValid = validateActivationCode(cleanDeviceId, cleanCode);

  const store = loadStore();
  let license = store.licenses.find(l => l.code === cleanCode);

  if (!license && isAlgorithmValid) {
    license = {
      code: cleanCode,
      deviceId: cleanDeviceId || '4630',
      mobile: mobile || '09123456789',
      status: 'active',
      type: 'لایسنس رسمی و مادام‌العمر',
      activatedAt: new Date().toLocaleDateString('fa-IR'),
      expiresAt: 'مادام‌العمر (بدون انقضا)'
    };
    store.licenses.push(license);
    saveStore(store);
  }

  if (!license) {
    return res.status(400).json({
      success: false,
      error: 'کد فعال‌سازی ۶ رقمی وارد شده با کد دیوایس ۴ رقمی همخوانی ندارد یا در سامانه تعریف نشده است.'
    });
  }

  if (license.status === 'revoked') {
    return res.status(403).json({
      success: false,
      error: 'این لایسنس توسط مدیریت غیرفعال شده است. با پشتیبانی ۰۹۱۵۹۶۵۰۸۰۲ تماس بگیرید.'
    });
  }

  // Bind to device
  license.deviceId = cleanDeviceId || license.deviceId || '4630';
  license.mobile = mobile || license.mobile || '09123456789';
  license.status = 'active';
  license.activatedAt = license.activatedAt || new Date().toLocaleDateString('fa-IR');
  saveStore(store);

  res.json({
    success: true,
    message: 'لایسنس با موفقیت تایید و به سخت‌افزار متصل شد.',
    license
  });
});

