// By default in real environment, if not connected to P_Motor AP, state is disconnected.
let isDeviceConnected = false;
let connectionStartTime: number | null = null;

app.get('/api/diag/ping', (req, res) => {
  const store = loadStore();
  const pingStart = Date.now();
  res.json({
    ok: isDeviceConnected,
    timestamp: pingStart,
    ssid: store.settings.targetSSID || 'P_Motor',
    ip: '192.168.4.1',
    connected: isDeviceConnected,
    latencyMs: isDeviceConnected ? Math.floor(2 + Math.random() * 5) : 9999,
    ecuStatus: isDeviceConnected ? 'ACTIVE_CAN2_OBD' : 'NO_SIGNAL'
  });
});

app.get('/api/diag/status', (req, res) => {
  const store = loadStore();
  const now = Date.now();
  const currentUptime = isDeviceConnected && connectionStartTime ? Math.floor((now - connectionStartTime) / 1000) : 0;

  res.json({
    connected: isDeviceConnected,
    ssid: store.settings.targetSSID || 'P_Motor',
    ip: isDeviceConnected ? '192.168.4.1' : '---.---.---.---',
    baudRate: isDeviceConnected ? '10400 BAUD' : 'INACTIVE',
    protocol: isDeviceConnected ? 'CAN 2.0B / K-LINE OBD-II' : 'WAITING_FOR_WIFI',
    ecuHandshake: isDeviceConnected ? 'ACTIVE' : 'DISCONNECTED',
    signalStrength: isDeviceConnected ? 98 : 0,
    lastPingMs: isDeviceConnected ? Math.floor(3 + Math.random() * 4) : 9999,
    uptimeSeconds: currentUptime,
    antiLostArmed: true,
    standbyMode: false,
    connectedSince: connectionStartTime
  });
});

// Toggle simulation disconnect / connect
app.post('/api/diag/simulate-disconnect', (req, res) => {
  const { disconnect } = req.body;
  const previousState = isDeviceConnected;
  isDeviceConnected = !disconnect;

  if (isDeviceConnected) {
    connectionStartTime = Date.now();
  } else {
    connectionStartTime = null;
  }

  const store = loadStore();
  if (!isDeviceConnected && previousState) {
    // Add disconnect log entry
    const newLog = {
      id: 'log-' + Date.now(),
      type: 'alarm' as const,
      title: 'قطع ناگهانی ارتباط وای‌فای',
      timestamp: 'امروز - ساعت ' + new Date().toLocaleTimeString('fa-IR'),
      timeAgo: 'لحظاتی پیش',
      subtext: 'خروج از محدوده خودرو / قطع اتصال وای‌فای دیاگ',
      details: 'آژیر حداکثر فعال شد • ویبره پالسی ممتد • اخطار قطع سیگنال به کاربر صادر گردید.',
      deviceId: '۶۴۲۴',
      ssid: store.settings.targetSSID || 'P_Motor',
      statusBadge: 'هشدار بلادرنگ فعال'
    };
    store.logs.unshift(newLog);
    saveStore(store);
  } else if (isDeviceConnected && !previousState) {
    // Add reconnect log entry
    const newLog = {
      id: 'log-' + Date.now(),
      type: 'connected' as const,
      title: 'اتصال موفق به شبکه وای‌فای P_Motor',
      timestamp: 'امروز - ساعت ' + new Date().toLocaleTimeString('fa-IR'),
      timeAgo: 'لحظاتی پیش',
      subtext: 'سیگنال سخت‌افزار دیاگ دریافت شد',
      details: 'ارتباط بی‌سیم با پورت OBD-II خودرو برقرار و پایش ضد فراموشی فعال گردید.',
      deviceId: '۶۴۲۴',
      ssid: store.settings.targetSSID || 'P_Motor',
      statusBadge: 'پایش فعال'
    };
    store.logs.unshift(newLog);
    saveStore(store);
  }

  res.json({
    success: true,
    connected: isDeviceConnected
  });
});

